questionvariables.text:
/* ---- choose the variant ---- */
shape  : rand([1,2,3]);          /* 1 = parallelogram, 2 = kite, 3 = trapezium */
iscong : rand([true,false]);     /* true = congruent case, false = distractor */
isP    : is(shape=1);
isK    : is(shape=2);
isTr   : is(shape=3);

/* ---- random vertex labels ---- */
letters : random_permutation([A,B,C,E,F,G,H,K,L,M,N,P,Q,R,S,T,U,V,W,X,Y,Z]);
va : letters[1];  vb : letters[2];  vc : letters[3];  vd : letters[4];
ve : letters[5];  vf : letters[6];

/* extra points hidden unless the parallelogram needs them */
show5 : false;  show6 : false;

/* ---- geometry ---- */
if shape = 1 then (
    /* parallelogram: va=top-left, vb=top-right, vc=bottom-right, vd=bottom-left */
    c1 : [0,4],  c2 : [6,4],  c3 : [7,0],  c4 : [1,0],
    c5 : [3,4],                                   /* E on top edge va-vb   */
    c6 : if iscong then [4,0] else [5.5,0],       /* F on bottom edge vd-vc */
    show5 : true,  show6 : true,
    bbox : [-1.5,6,9,-1.5],
    tri1 : [c1,c4,c5],  tri2 : [c3,c2,c6],
    t1a : va, t1b : vd, t1c : ve,
    t2a : vc, t2b : vb, t2c : vf,
    shapename : "parallelogram"
);

if shape = 2 then (
    /* kite: va=top, vb=right, vc=bottom, vd=left; axis is va-vc */
    c1 : [3,5],  c2 : [6,3],  c3 : [3,0],  c4 : [0,3],
    c5 : [0,0],  c6 : [0,0],
    bbox : [-1.5,6,7.5,-1.5],
    if iscong then (
        tri1 : [c1,c2,c3],  tri2 : [c1,c4,c3],
        t1a : va, t1b : vb, t1c : vc,
        t2a : va, t2b : vd, t2c : vc
    ) else (
        tri1 : [c1,c4,c2],  tri2 : [c3,c4,c2],
        t1a : va, t1b : vd, t1c : vb,
        t2a : vc, t2b : vd, t2c : vb
    ),
    shapename : "kite"
);

if shape = 3 then (
    /* trapezium: va=top-left, vb=top-right, vc=bottom-right, vd=bottom-left; va vb || vd vc */
    c3 : [7,0],  c4 : [0,0],                       /* base vertices C, D fixed */
    if iscong then ( c1 : [2,4],  c2 : [5,4] )     /* isosceles top */
              else ( c1 : [1,4],  c2 : [4,4] ),    /* scalene top   */
    c5 : [0,0],  c6 : [0,0],
    bbox : [-1.5,6,9,-1.5],
    tri1 : [c1,c3,c4],  tri2 : [c2,c4,c3],
    t1a : va, t1b : vc, t1c : vd,
    t2a : vb, t2b : vd, t2c : vc,
    shapename : "trapezium"
);

/* ---- label offsets (pixels) ---- */
o1 : [-8,12];  o2 : [12,8];  o3 : [12,-8];  o4 : [-12,-8];  o5 : [0,14];  o6 : [0,-16];

/* ---- correct answer ---- */
ta : random_permutation( if iscong then [["yes",true],["no",false]]
                                    else [["yes",false],["no",true]] );
